package com.loottableviewer;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

@Singleton
public class ItemCategoryService
{
    private final ItemManager itemManager;

    @Inject
    public ItemCategoryService(ItemManager itemManager)
    {
        this.itemManager = itemManager;
    }

    public String categorize(int itemId, String itemName)
    {
        String safeName = itemName == null ? "" : itemName.toLowerCase();

        if (safeName.equals("nothing"))
        {
            return "Other";
        }

        if (safeName.contains("coin"))
        {
            return "Coins";
        }

        if (isRune(safeName))
        {
            return "Runes";
        }

        if (isAmmunition(safeName))
        {
            return "Ammunition";
        }

        if (itemId > 0)
        {
            try
            {
                ItemComposition item = itemManager.getItemComposition(itemId);
                if (item != null)
                {
                    if (isArmourName(safeName))
                    {
                        return "Armour";
                    }

                    if (isWeaponName(safeName))
                    {
                        return "Weapons";
                    }
                }
            }
            catch (Exception ignored)
            {
            }
        }

        if (isArmourName(safeName))
        {
            return "Armour";
        }

        if (isWeaponName(safeName))
        {
            return "Weapons";
        }

        return "Other";
    }

    private boolean isRune(String name)
    {
        return name.endsWith(" rune")
                || name.contains(" rune ")
                || name.equals("rune essence")
                || name.equals("pure essence");
    }

    private boolean isAmmunition(String name)
    {
        return name.contains(" arrow")
                || name.contains(" arrows")
                || name.contains(" bolt")
                || name.contains(" bolts")
                || name.contains(" dart")
                || name.contains(" darts")
                || name.contains(" knife")
                || name.contains(" knives")
                || name.contains(" javelin")
                || name.contains(" thrownaxe");
    }

    private boolean isWeaponName(String name)
    {
        return name.contains("sword")
                || name.contains("dagger")
                || name.contains("scimitar")
                || name.contains("mace")
                || name.contains("warhammer")
                || name.contains("spear")
                || name.contains("halberd")
                || name.contains("bow")
                || name.contains("staff")
                || name.contains("wand")
                || name.contains("axe")
                || name.contains("maul")
                || name.contains("whip")
                || name.contains("hasta")
                || name.contains("crossbow");
    }

    private boolean isArmourName(String name)
    {
        return name.contains("helm")
                || name.contains("helmet")
                || name.contains("body")
                || name.contains("platebody")
                || name.contains("platelegs")
                || name.contains("plateskirt")
                || name.contains("shield")
                || name.contains("kiteshield")
                || name.contains("sq shield")
                || name.contains("boots")
                || name.contains("gloves")
                || name.contains("vambraces")
                || name.contains("chaps")
                || name.contains("skirt")
                || name.contains("robe")
                || name.contains("coif")
                || name.contains("mail");
    }
}

package com.loottableviewer;

import com.loottableviewer.model.DropEntry;
import com.loottableviewer.model.LootLookupResult;
import com.loottableviewer.model.ReceivedItem;
import java.io.IOException;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class LootTableLookupService
{
    private final OsrsWikiClient wikiClient;
    private final WikiDropParser parser;

    @Inject
    public LootTableLookupService(OsrsWikiClient wikiClient, WikiDropParser parser)
    {
        this.wikiClient = wikiClient;
        this.parser = parser;
    }

    public LootLookupResult lookup(
            String sourceName,
            String normalizedSourceName,
            String sourceType,
            List<ReceivedItem> receivedItems,
            Consumer<String> statusCallback)
    {
        try
        {
            if (statusCallback != null)
            {
                statusCallback.accept("Searching OSRS Wiki...");
            }

            OsrsWikiClient.WikiPageData page = wikiClient.findPage(normalizedSourceName);
            if (page == null)
            {
                if (statusCallback != null)
                {
                    statusCallback.accept("No OSRS Wiki page found.");
                }
                return LootLookupResult.empty(sourceName, normalizedSourceName, sourceType, receivedItems, "No OSRS Wiki page found.");
            }

            if (statusCallback != null)
            {
                statusCallback.accept("Page found: " + page.getTitle() + ". Parsing loot rows...");
            }

            String wikitext = page.getWikitext();
            List<DropEntry> entries = parser.parse(wikitext);
            String status = buildStatusMessage(page.getTitle(), wikitext, entries);

            if (statusCallback != null)
            {
                statusCallback.accept(status);
            }

            return new LootLookupResult(
                    sourceName,
                    normalizedSourceName,
                    sourceType,
                    page.getTitle(),
                    page.getUrl(),
                    receivedItems,
                    entries,
                    status
            );
        }
        catch (IOException ex)
        {
            String message = "Wiki lookup failed: " + ex.getMessage();
            if (statusCallback != null)
            {
                statusCallback.accept(message);
            }
            return LootLookupResult.empty(sourceName, normalizedSourceName, sourceType, receivedItems, message);
        }
        catch (RuntimeException ex)
        {
            String message = "Wiki parsing failed: " + ex.getMessage();
            if (statusCallback != null)
            {
                statusCallback.accept(message);
            }
            return LootLookupResult.empty(sourceName, normalizedSourceName, sourceType, receivedItems, message);
        }
    }

    private String buildStatusMessage(String pageTitle, String wikitext, List<DropEntry> entries)
    {
        if (entries != null && !entries.isEmpty())
        {
            return "Loaded " + entries.size() + " wiki drop rows.";
        }

        if (wikitext == null || wikitext.isBlank())
        {
            return "Wiki page found, but no wikitext was returned.";
        }

        String lower = wikitext.toLowerCase(Locale.ENGLISH);
        if (lower.contains("drop") || lower.contains("loot") || lower.contains("reward"))
        {
            return "Wiki page found (" + pageTitle + "), but no recognizable loot-table rows were found.";
        }

        return "Wiki page found, but no drop rows were parsed.";
    }
}

package com.loottableviewer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("loottableviewer")
public interface LootTableViewerConfig extends Config
{
    @ConfigItem(
        keyName = "maxDropRows",
        name = "Max drop rows",
        description = "Maximum number of wiki drop rows shown in the panel"
    )
    default int maxDropRows()
    {
        return 500;
    }

    @ConfigItem(
        keyName = "showReceivedItems",
        name = "Show received items",
        description = "Show the exact items from the latest loot event"
    )
    default boolean showReceivedItems()
    {
        return true;
    }

    @ConfigItem(
        keyName = "includeAlwaysDrops",
        name = "Include always drops",
        description = "Include always/common guaranteed entries from the wiki output"
    )
    default boolean includeAlwaysDrops()
    {
        return true;
    }

    @ConfigItem(
        keyName = "wikiUserAgent",
        name = "Wiki user-agent",
        description = "User-Agent sent to the OSRS Wiki API"
    )
    default String wikiUserAgent()
    {
        return "RuneLite Loot Table Viewer";
    }
}

