    private static DropEntry requireDrop(List<DropEntry> drops, String itemName)
    {
        for (DropEntry drop : drops)
        {
            if (itemName.equals(drop.getItemName()))
            {
                return drop;
            }
        }

        throw new AssertionError("Missing drop: " + itemName);
    }
